import ast, nbformat
def unescape(line):
    # decode only \\n, \\", \\', \\\\ (the escapes present in the corrupted runs)
    out, i = [], 0
    while i < len(line):
        if line[i] == '\\' and i + 1 < len(line) and line[i+1] in 'n"\'\\':
            out.append({'n': '\n', '"': '"', "'": "'", '\\': '\\'}[line[i+1]]); i += 2
        else:
            out.append(line[i]); i += 1
    return ''.join(out)

def repair(path, cells, threshold=4):
    nb = nbformat.read(path, as_version=4)
    for i in cells:
        src = '\n'.join(unescape(l) if l.count('\\n') >= threshold else l
                        for l in nb.cells[i].source.split('\n'))
        try:
            ast.parse(src); print('OK', path, i)
        except SyntaxError as e:
            print('HAND-FIX', path, i, e)
        nb.cells[i].source = src
    nbformat.write(nb, path)

