from hts.materials import jc_vs_tb
def current_sharing_temperature(I_op, B_peak, A_sc, Tc=90.0, **jc_kw):
    f = lambda T: jc_vs_tb(T=T, B=B_peak, Tc=Tc, **jc_kw)*A_sc - I_op
    if f(1.0) < 0:
        return None  # not superconducting at this (B, I) even at 1 K
    return brentq(f, 1.0, Tc - 1e-6)

